#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/random/random.h>

/* N threads loop, yielding after computing the next number in a
 * per-thread saturation arithmetic PRNG stream.  Notice that two has
 * no common factors with three, so every two steps the phase in the
 * 3-cycle changes by 2, which visits all three states.  And every
 * three steps matches a 3-cycle, meaning that relative to that state
 * the 5-cycle advanced by 3, which is also mutually prime, etc...
 *
 * Thus every stream here is guaranteed to enter every state with the
 * same probability and in the same number of instructions, resulting
 * in a uniform test distribution of thread states.
 */
#define NUM_THREADS 5
#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static struct k_thread worker_threads[NUM_THREADS];
static K_THREAD_STACK_ARRAY_DEFINE(worker_stacks, NUM_THREADS, STACK_SIZE);

/* The number of threads that have run since the current thread last
 * ran.  With identical deadlines, this can never be more than
 * NUM_THREADS.
 */
static int threads_between[NUM_THREADS];

static k_tid_t thread_Order[NUM_THREADS * 16];
static int n_exec;

static int expected_deadline[NUM_THREADS];

void worker_fn(void *p1, void *p2, void *p3)
{
	int tid = POINTER_TO_INT(p1);

	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	while (n_exec < ARRAY_SIZE(thread_Order)) {
		for (int i = 0; i < NUM_THREADS; i++) {
			if (i == tid) {
				threads_between[i] = 0;
			} else {
				threads_between[i]++;
			}
		}

		thread_Order[n_exec++] = k_current_get();

		if (expected_deadline[tid]) {
			k_thread_deadline_set(k_current_get(),
					      expected_deadline[tid]);
		}

		k_yield();
	}
}

ZTEST(suite_deadline, test_deadline)
{
	int i;

	n_exec = 0;

	for (i = 0; i < NUM_THREADS; i++) {
		threads_between[i] = 0;

		/* Pick a random deadline for each thread.  Use a
		 * fairly large range (up to ~16M cycles) to avoid
		 * wraparound issues during the test.
		 */
		expected_deadline[i] = sys_rand32_get() & 0x00fffffe;
		if (expected_deadline[i] == 0) {
			expected_deadline[i] = 2;
		}

		k_thread_create(&worker_threads[i],
				worker_stacks[i], STACK_SIZE,
				worker_fn, INT_TO_POINTER(i), NULL, NULL,
				K_PRIO_PREEMPT(2), 0, K_FOREVER);

		k_thread_deadline_set(&worker_threads[i], expected_deadline[i]);
	}

	/* Start them all at once.  This thread is running at a
	 * higher priority (1 vs. 2), so they will all get queued
	 * simultaneously.
	 */
	k_priority_set(k_current_get(), K_PRIO_PREEMPT(1));
	for (i = 0; i < NUM_THREADS; i++) {
		k_thread_start(&worker_threads[i]);
	}

	/* Sleep, letting the workers run */
	k_msleep(100);

	/* Validate that they ran in deadline order */
	for (i = 0; i < NUM_THREADS; i++) {
		k_tid_t curr = thread_Order[i];
		int c_idx = curr - &worker_threads[0];

		if (i > 0) {
			k_tid_t prev = thread_Order[i - 1];
			int p_idx = prev - &worker_threads[0];

			zassert_true(expected_deadline[c_idx] >=
				     expected_deadline[p_idx],
				     "threads ran out of deadline order");
		}
	}

	/* Now test with identical deadlines, where each thread resets
	 * its own deadline on each iteration.  Every thread must run
	 * once in every NUM_THREADS steps.
	 */
	for (i = 0; i < NUM_THREADS; i++) {
		k_thread_abort(&worker_threads[i]);
	}

	n_exec = 0;

	for (i = 0; i < NUM_THREADS; i++) {
		threads_between[i] = 0;
		expected_deadline[i] = 100000;

		k_thread_create(&worker_threads[i],
				worker_stacks[i], STACK_SIZE,
				worker_fn, INT_TO_POINTER(i), NULL, NULL,
				K_PRIO_PREEMPT(2), 0, K_FOREVER);

		k_thread_deadline_set(&worker_threads[i], expected_deadline[i]);
		k_thread_start(&worker_threads[i]);
	}

	k_msleep(100);

	for (i = 0; i < NUM_THREADS; i++) {
		zassert_true(threads_between[i] < NUM_THREADS,
			     "thread starved despite equal deadlines");
		k_thread_abort(&worker_threads[i]);
	}

	/* Test negative/expired deadlines, and ensure that a
	 * re-queued thread does not preempt a running one with an
	 * expired deadline
	 */
	n_exec = 0;

	for (i = 0; i < NUM_THREADS; i++) {
		threads_between[i] = 0;
		expected_deadline[i] = -100;

		k_thread_create(&worker_threads[i],
				worker_stacks[i], STACK_SIZE,
				worker_fn, INT_TO_POINTER(i), NULL, NULL,
				K_PRIO_PREEMPT(2), 0, K_FOREVER);

		k_thread_deadline_set(&worker_threads[i], expected_deadline[i]);
		k_thread_start(&worker_threads[i]);
	}

	k_msleep(100);

	for (i = 0; i < NUM_THREADS; i++) {
		zassert_true(threads_between[i] < NUM_THREADS,
			     "thread starved with negative deadlines");
		k_thread_abort(&worker_threads[i]);
	}
}

ZTEST_SUITE(suite_deadline, NULL, NULL, NULL, NULL, NULL);
